-- French descriptions (by website, so the right entity is found even if its slug differs)
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%zeliq.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent commercial IA intégré à la plateforme de prospection Zeliq, qui trouve des leads correspondant à votre ICP, vérifie les coordonnées, construit vos séquences et synchronise les relances avec votre CRM.', 'AI sales agent inside the Zeliq prospecting platform that finds ICP leads, validates contact data, builds outreach sequences and syncs follow-ups to the CRM.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%lagrowthmachine.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme française de prospection multicanale (LinkedIn, e-mail, appels) avec un Reply Agent qui répond aux réponses LinkedIn et un serveur MCP pour piloter vos campagnes depuis Claude ou ChatGPT.', 'French multichannel prospecting platform (LinkedIn, email, calls) with a Reply Agent that answers LinkedIn replies and an MCP server to run campaigns from Claude or ChatGPT.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%swiftask.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme française d''agents IA pour l''entreprise, qui permet de créer, orchestrer et gouverner des agents no-code connectés à vos outils et données, avec automatisations et déclencheurs.', 'French enterprise AI agent platform to build, orchestrate and govern no-code agents connected to business tools and data, with task automations and triggers.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%leonar.app%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'ATS et CRM « AI-first » pour cabinets de recrutement, avec agent de sourcing IA, scoring des candidats, séquences multicanales, API REST et serveur MCP.', 'AI-first ATS and CRM for recruitment agencies with an AI sourcing agent, candidate scoring, multichannel outreach sequences, REST API and MCP server.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%vocca.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent vocal IA français pour cabinets et centres de santé, qui répond aux appels des patients 24h/24, prend et déplace les rendez-vous dans votre logiciel et envoie les rappels.', 'French AI voice agent for healthcare practices that answers patient calls 24/7, books and reschedules appointments in the practice software and sends reminders.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%klark.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'IA générative française pour le service client : un agent de chat autonome sur votre site avec transfert vers un humain, et un copilote helpdesk qui rédige et traduit les réponses aux e-mails.', 'French generative AI for customer service: an autonomous website chat agent with human handoff and a helpdesk copilot that drafts and translates email replies.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%botmind.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Suite IA française pour le service client avec modules chatbot, réponse aux e-mails, assistance aux agents et callbot, connectés à Zendesk, Salesforce, Shopify et aux plateformes CCaaS.', 'French AI customer service suite with chatbot, email reply, agent-assist and callbot modules plugged in' || 'to Zendesk, Salesforce, Shopify and CCaaS platforms.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%tolk.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Écosystème d''IA agentique français pour l''expérience client, qui déploie des agents IA sur les messageries et outils de support comme WhatsApp, Messenger, Zendesk et Intercom.', 'French agentic AI ecosystem for customer experience that deploys AI agents on messaging apps and support tools such as WhatsApp, Messenger, Zendesk and Intercom.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%lightpanda.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Navigateur headless léger conçu pour les agents IA et l''automatisation, disponible en open source et en service cloud, accessible via CDP (Puppeteer, Playwright) et MCP.', 'Lightweight headless browser built for AI agents and automation, available as open source and as a cloud service with CDP (Puppeteer, Playwright) and MCP access.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%textcortex.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Espace de travail IA berlinois où les équipes créent des agents personnalisés avec skills, connecteurs et bases de connaissances pour rédiger, répondre à partir des connaissances internes et automatiser des workflows.', 'Berlin-based AI workspace where teams build custom agents with skills, connectors and knowledge bases to write content, answer from company knowledge and automate workflows.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%tacto.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents IA pour les achats industriels qui gèrent l''onboarding fournisseurs, rapprochent les confirmations de commande des PO, analysent les dépenses, évaluent les offres et assurent la conformité ESG/CBAM.', 'AI agents for industrial procurement that onboard suppliers, match order confirmations to POs, analyze spend, evaluate bids and run ESG/CBAM compliance checks.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%sipgate.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent téléphonique IA (anciennement sipgate AI Agents) qui répond aux appels professionnels en neuf langues, s''appuie sur votre base de connaissances, interroge CRM ou boutique et transfère les appels ou envoie des résumés.', 'AI phone agent (formerly sipgate AI Agents) that answers business calls in nine languages, uses your knowledge base, queries CRM or shop data and forwards calls or sends summaries.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%taktile.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme de décision IA dotée d''agents de souscription qui analysent les documents financiers, vérifient les entreprises sur le web et étudient les états financiers pour les décisions de crédit et de risque PME.', 'AI decision platform with underwriting agents that parse financial documents, verify businesses on the web and analyze statements to support SMB credit and risk decisions.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%interloom.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme d''opérations pour entreprises dont les agents IA répondent aux questions, traitent les dossiers et exécutent des étapes de workflows grâce à un graphe de contexte sur la façon dont les experts résolvent le back-office.', 'Enterprise operations platform whose AI agents answer questions, process cases and run workflow steps using a context graph of how experts actually resolve back-office work.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%peec.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme de visibilité dans la recherche IA qui exécute chaque jour vos prompts suivis sur ChatGPT, Perplexity, Gemini et d''autres LLM et mesure mentions de marque, sources et concurrents.', 'AI search visibility platform that runs your tracked prompts daily across ChatGPT, Perplexity, Gemini and other LLMs and reports brand mentions, sources and competitors.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%sap.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents IA intégrés aux applications métier SAP qui planifient et exécutent des étapes dans la finance, les achats, la supply chain, les RH et le service client, par exemple le routage de dossiers et le procure-to-pay.', 'AI agents embedded in SAP business applications that plan and execute steps across finance, procurement, supply chain, HR and customer service processes, e.g. case routing and procure-to-pay.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%zeeg.me%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent téléphonique IA intégré à la plateforme de prise de rendez-vous zeeg qui gère les appels entrants et sortants, réserve les rendez-vous dans l''agenda, route les appels et consigne les transcriptions dans le CRM.', 'AI phone agent built in' || 'to the zeeg scheduling platform that takes inbound and outbound calls, books appointments in the calendar, routes calls and logs transcripts in the CRM.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%yourang.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Assistant téléphonique IA italien pour les PME qui répond aux appels 24h/24, prend les réservations et rendez-vous, et s''étend aux conversations WhatsApp, Instagram et Facebook.', 'Italian AI phone assistant for SMBs that answers calls 24/7, books tables and appointments, and extends to WhatsApp, Instagram and Facebook conversations.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%voicierge.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents vocaux IA sur mesure qui répondent aux lignes téléphoniques de l''entreprise 24h/24 dans toutes les langues, prennent les rendez-vous, informent et transfèrent les appels, en cloud ou on-premise.', 'Custom AI voice agents that answer business phone lines 24/7 in any language, book appointments, give information and route calls, deployable in cloud or on-premise.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%aptiva.cloud%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents vocaux IA italiens qui répondent aux appels et en passent 24h/24, qualifient les leads et prennent les rendez-vous, avec serveurs et enregistrements hébergés en Italie.', 'Italian AI voice agents that answer and place phone calls 24/7, qualify leads and book appointments, with servers and recordings hosted in Italy.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%mycentralino.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Réceptionniste IA intégrée à un standard téléphonique cloud italien, qui répond aux appels 24h/24, prend et déplace les rendez-vous, transfère les appels et envoie les confirmations.', 'AI receptionist built in' || 'to an Italian cloud phone system that answers calls 24/7, books and reschedules appointments, transfers calls and sends confirmations.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%skillvue.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme IA d''évaluation des compétences qui mène des évaluations adaptatives audio, vidéo et conversationnelles des candidats et salariés, puis les note, classe et présélectionne.', 'AI skills-assessment platform that runs adaptive audio, video and conversational assessments of candidates and employees, then scores, ranks and shortlists them.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%klaaryo.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent IA conversationnel de recrutement qui présélectionne les candidats par chat, planifie les entretiens selon les agendas des managers, envoie des rappels et produit des scorecards.', 'Conversational AI recruiting agent that pre-screens candidates by chat, schedules interviews against manager calendars, sends reminders and produces scorecards.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%get-cato.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agent IA pour les marchés publics italiens qui repère les appels d''offres pertinents, analyse les cahiers des charges, étudie la concurrence et rédige les documents techniques et financiers.', 'AI agent for Italian public tenders that finds relevant bids, analyzes tender documents and requirements, studies competitors and drafts technical and financial bid documents.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%alomana.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme entreprise milanaise pour créer et déployer des agents IA autonomes (« operators ») qui exécutent des processus métier de bout en bout dans une instance privée et auditable.', 'Milan-based enterprise platform to build and deploy autonomous AI agents (''operators'') that run business processes end-to-end in a private, auditable instance.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%sibill.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme de gestion financière pour les PME italiennes et les experts-comptables, dont l''IA agentique rapproche mouvements bancaires et factures, catégorise les transactions et synchronise les écritures.', 'Financial management platform for Italian SMBs and accountants whose agentic AI reconciles bank movements with invoices, categorizes transactions and syncs accounting entries.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%simpliciter.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Assistant juridique IA italien qui recherche la loi et la jurisprudence italiennes, analyse les documents importés, révise les contrats et rédige les actes, aussi utilisable via un serveur MCP.', 'Italian AI legal assistant that researches Italian law and case law, analyzes uploaded documents, reviews contracts and drafts legal filings, also usable via an MCP server.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%responsa.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme d''IA conversationnelle pour entreprises dont les agents vocaux et chat absorbent de forts volumes d''appels, consultent et mettent à jour les systèmes, ouvrent des demandes et transfèrent aux opérateurs avec le contexte.', 'Enterprise conversational AI platform whose voice and chat agents handle high call volumes, read and update enterprise systems, open requests and hand off to operators with context.');

select refresh_rankings();

-- Check: the new agents, with their page and French description
select e.name, e.slug as page, (t.value is not null) as french from entities e left join entity_i18n t on t.entity_id = e.id and t.lang = 'fr'
 where e.type = 'agent' and e.website ilike any (array['%zeliq.com%', '%lagrowthmachine.com%', '%swiftask.ai%', '%leonar.app%', '%vocca.com%', '%klark.ai%', '%botmind.io%', '%tolk.ai%', '%lightpanda.io%', '%textcortex.com%', '%tacto.ai%', '%sipgate.ai%', '%taktile.com%', '%interloom.com%', '%peec.ai%', '%sap.com%', '%zeeg.me%', '%yourang.ai%', '%voicierge.ai%', '%aptiva.cloud%', '%mycentralino.com%', '%skillvue.ai%', '%klaaryo.com%', '%get-cato.com%', '%alomana.com%', '%sibill.com%', '%simpliciter.ai%', '%responsa.ai%']) order by e.name;
